def solve(payload):
    tasks = payload['tasks']
    return {'order': [t['id'] for t in sorted(tasks, key=lambda t: t['id'])], 'start': {}, 'finish': {}, 'makespan': 0}

def solve(payload):
    import copy
    p = copy.deepcopy(payload)
    p['tasks'] = list(reversed(p['tasks']))
    return {'error': 'invalid'} if not p.get('tasks') else {'order': [t['id'] for t in p['tasks']], 'start': {}, 'finish': {}, 'makespan': 0}
